"""Every furniture block: its model boxes, textures, recipe and description.
A box is (x1, y1, z1, x2, y2, z2, texture) in pixels, drawn facing north (front at z=0, back at z=16).
texture is a key of the block's "tex" map, or a dict of face -> key ("*" = the other faces).
A box can end with {"rot": (axis, angle, origin)} to tilt it."""

def T(n): return "minecraft:block/" + n
def O(n): return "onepiece:block/" + n
def F(n): return "onepiece:block/furniture/" + n


def legs(inset, size, height, t, y0=0):
    a, b = inset, 16 - inset - size
    return [(x, y0, z, x + size, height, z + size, t) for x in (a, b) for z in (a, b)]


# id prefix, display name, planks texture, stripped log texture, planks item, slab item, stripped log item, flammable
WOODS = [
    ("oak", "Oak", T("oak_planks"), T("stripped_oak_log"), "minecraft:oak_planks", "minecraft:oak_slab", "minecraft:stripped_oak_log"),
    ("spruce", "Spruce", T("spruce_planks"), T("stripped_spruce_log"), "minecraft:spruce_planks", "minecraft:spruce_slab", "minecraft:stripped_spruce_log"),
    ("birch", "Birch", T("birch_planks"), T("stripped_birch_log"), "minecraft:birch_planks", "minecraft:birch_slab", "minecraft:stripped_birch_log"),
    ("dark_oak", "Dark Oak", T("dark_oak_planks"), T("stripped_dark_oak_log"), "minecraft:dark_oak_planks", "minecraft:dark_oak_slab", "minecraft:stripped_dark_oak_log"),
    ("sakura", "Sakura", O("sakura_planks"), O("stripped_sakura_log"), "onepiece:sakura_planks", "onepiece:sakura_slab", "onepiece:stripped_sakura_log"),
    ("palm", "Palm", O("palm_planks"), O("stripped_palm_log"), "onepiece:palm_planks", "onepiece:palm_slab", "onepiece:stripped_palm_log"),
]


