def cloth_table(color, label):
    return dict(id=f"{color}_tablecloth_table", name=f"{label} Tablecloth Table", mat="wood", cat="top",
                tex={"p": T("oak_planks"), "l": T("stripped_oak_log"), "w": T(f"{color}_wool")},
                boxes=[(0, 13, 0, 16, 15, 16, "p"), (0, 15, 0, 16, 16, 16, "w"), (0, 10, 0, 16, 15, 0.5, "w"), (0, 10, 15.5, 16, 15, 16, "w"),
                       (0, 10, 0.5, 0.5, 15, 15.5, "w"), (15.5, 10, 0.5, 16, 15, 15.5, "w")] + legs(1, 2, 13, "l"),
                shapeless=(["onepiece:oak_table", f"minecraft:{color}_carpet"], 1),
                desc="A table dressed with a cloth, for taverns, restaurants and royal dinners.")


def cushion(color, label):
    return dict(id=f"{color}_floor_cushion", name=f"{label} Floor Cushion", mat="wool", cat="other", seat=3,
                tex={"w": T(f"{color}_wool"), "g": T("gold_block")},
                boxes=[(2, 0, 2, 14, 3, 14, "w"), (7, 3, 7, 9, 3.5, 9, "g")] + [(x, 0, z, x + 1, 1, z + 1, "g") for x in (1.5, 13.5) for z in (1.5, 13.5)],
                recipe=(["SWS"], {"S": "minecraft:string", "W": f"minecraft:{color}_wool"}, 2),
                desc="A Wano zabuton to sit on the floor. Right-click with an empty hand to sit down.")


def rug(rid, label, center, border):
    return dict(id=rid, name=label, mat="wool", cat="other",
                tex={"c": T(f"{center}_wool"), "b": T(f"{border}_wool")},
                boxes=[(1, 0, 1, 15, 1, 15, "c"), (0, 0, 0, 16, 1, 1, "b"), (0, 0, 15, 16, 1, 16, "b"), (0, 0, 1, 1, 1, 15, "b"), (15, 0, 1, 16, 1, 15, "b")],
                recipe=(["BCB"], {"B": f"minecraft:{border}_carpet", "C": f"minecraft:{center}_carpet"}, 3),
                desc="A rug with a border, flat on the floor like a carpet.")


def curtain(color, label):
    folds = [(x, 0, 13.5 if i % 2 else 14.5, x + 2, 15, 15 if i % 2 else 16, "w") for i, x in enumerate(range(0, 16, 2))]
    return dict(id=f"{color}_curtain", name=f"{label} Curtain", mat="wool", cat="other", solid=False,
                tex={"w": T(f"{color}_wool"), "r": T("dark_oak_planks")},
                boxes=folds + [(0, 15, 13, 16, 16, 16, "r")],
                recipe=(["I", "W", "W"], {"I": "minecraft:stick", "W": f"minecraft:{color}_wool"}, 2),
                desc="Curtains with a rail. Put them in front of a window. You can walk through them.")


def balustrade(bid, label, stone, top, recipe):
    return dict(id=bid, name=label, mat="stone", cat="top", tex={"s": stone, "t": top},
                boxes=[(0, 13, 4, 16, 16, 12, "t"), (0, 0, 4, 16, 3, 12, "t"),
                       (1.5, 3, 6, 4.5, 13, 10, "s"), (6.5, 3, 6, 9.5, 13, 10, "s"), (11.5, 3, 6, 14.5, 13, 10, "s")],
                recipe=recipe, desc="A carved stone railing for balconies, bridges and grand stairs.")


def crate_box(t="p", e="e"):
    return [(2, 0, 2, 14, 6, 14, {"up": "i", "*": t}), (2, 0, 1.5, 14, 1, 2, e), (2, 5, 1.5, 14, 6, 2, e)]


